script:
// A streaming service: nodes, the edges between them, then the groups
// around them, inner groups before the boundary that holds them. Nothing
// is placed by hand: wb.layout() lines it all up at the end.
const size = { width: 150, height: 56 };

// Each node names the code that defines it; Sessions is left unlinked.
const definedIn = {
  web: "web-app", tv: "tv-app", gateway: "gateway", playback: "playback",
  drm: "drm", catalog: "catalog", search: "search", transcoder: "transcoder",
  segments: "segments", accounts: "accounts", events: "events",
};

const node = (id, kind, label, tag) =>
  wb.node({ id, kind, label, tag, ...size, code: definedIn[id] });

const n = {
  viewer: node("viewer", "person", "Viewer"),
  web: node("web", "container", "Web app", "Container · React"),
  tv: node("tv", "container", "TV app", "Container · Kotlin"),
  payments: node("payments", "external", "Payments", "External · Stripe"),
  gateway: node("gateway", "container", "API gateway", "Container · Go"),
  playback: node("playback", "container", "Playback API", "Container · Go"),
  drm: node("drm", "container", "DRM licences", "Container · Go"),
  catalog: node("catalog", "container", "Catalog API", "Container · Node.js"),
  search: node("search", "container", "Search", "Container · Elastic"),
  transcoder: node("transcoder", "container", "Transcoder", "Container · FFmpeg"),
  segments: node("segments", "database", "Video segments", "Database · S3"),
  accounts: node("accounts", "database", "Accounts", "Database · Postgres"),
  sessions: node("sessions", "database", "Sessions", "Database · Redis"),
  events: node("events", "queue", "Events", "Queue · Kafka"),
};

// Each edge names its call site, the line where one side calls the other.
// A person's edges are not code; the edge to Payments is not linked yet.
// Labels say how each call travels.
const wires = [];

const link = (from, to, options = {}) =>
  wires.push({ from, to, path: wb.edge({ from: n[from], to: n[to], ...options }) });

link("viewer", "web");
link("viewer", "tv");
link("web", "gateway", { label: "HTTPS", code: "web-search-call" });
link("tv", "gateway", { label: "HTTPS", code: "tv-play-call" });
link("tv", "payments", { dashed: true, code: [] });
link("gateway", "playback", { label: "gRPC", code: "gateway-manifest" });
link("gateway", "catalog", { label: "gRPC", code: ["gateway-title", "gateway-search"] });
link("playback", "drm", { code: "playback-licence" });
link("drm", "accounts", { label: "SQL", code: "drm-plan-query" });
link("catalog", "search", { code: "catalog-elastic" });
link("search", "sessions", { code: "search-history" });
link("transcoder", "segments", { code: "transcoder-put" });
link("segments", "events", { label: "S3 event", code: "segments-notify" });

// Groups, inner first. Colour says which team owns what.
const g = {
  clients: wb.group({ id: "clients", label: "Client apps", around: [n.web, n.tv], color: "sky" }),
  playback: wb.group({ id: "playback-team", label: "Playback", around: [n.playback, n.drm], color: "violet" }),
  catalog: wb.group({ id: "catalog-team", label: "Catalog", around: [n.catalog, n.search], color: "amber" }),
  encoding: wb.group({ id: "encoding-team", label: "Encoding", around: [n.transcoder, n.segments], color: "coral" }),
  data: wb.group({ id: "data-team", label: "Data", around: [n.accounts, n.sessions, n.events], color: "green" }),
};
g.platform = wb.group({
  id: "platform",
  label: "Streaming platform",
  tag: "Software system",
  around: [n.gateway, g.playback, g.catalog, g.encoding, g.data],
});

await wb.layout({ direction: "right" });

// Which group each node sits in, to light the groups a request passes.
const home = {
  web: "clients", tv: "clients",
  playback: "playback", drm: "playback",
  catalog: "catalog", search: "catalog",
  transcoder: "encoding", segments: "encoding",
  accounts: "data", sessions: "data", events: "data",
};

// Each scenario is one request; each of its frames is a step, and
// `frame.data.moves` are the movements in that step, which run together.
// A move against a wire's direction is a reply unless it says otherwise.
const movesOf = (frame) => frame?.data?.moves ?? [];
const scenarioMoves = () => (wb.scenario?.frames ?? []).flatMap(movesOf);

const findWire = (from, to) => {
  const forward = wires.find((w) => w.from === from && w.to === to);
  if (forward) return { line: forward, reverse: false };
  return { line: wires.find((w) => w.from === to && w.to === from), reverse: true };
};

const light = () => {
  const all = scenarioMoves();
  if (!all.length) {
    for (const element of [...Object.values(n), ...Object.values(g)]) element.dataset.state = "default";
    for (const { path } of wires) path.dataset.state = "default";
    return;
  }

  const sofar = wb.scenario.frames.slice(0, wb.frameIndex + 1).flatMap(movesOf);
  const touched = new Set(all.flatMap((m) => [m.from, m.to]));
  const reached = new Set(sofar.flatMap((m) => [m.from, m.to]));
  const used = new Set(sofar.map((m) => findWire(m.from, m.to).line));
  const groups = new Set([...touched].map((key) => home[key]).filter(Boolean));

  for (const [key, element] of Object.entries(n))
    element.dataset.state = reached.has(key) ? "active" : touched.has(key) || home[key] ? "default" : "dimmed";
  for (const [key, element] of Object.entries(g))
    element.dataset.state = key === "platform" ? "default" : groups.has(key) ? "active" : "dimmed";
  for (const w of wires) {
    const ours = all.some((m) => findWire(m.from, m.to).line === w);
    w.path.dataset.state = used.has(w) ? "active" : ours ? "default" : "dimmed";
  }
};

const wait = (ms, signal) =>
  new Promise((resolve) => {
    const timer = setTimeout(resolve, ms);
    signal.addEventListener("abort", () => { clearTimeout(timer); resolve(); }, { once: true });
  });

// One move: a token rides its wire once and rests at the far end. The
// reader replays the step to see it again.
const move = async ({ from, to, label, reply, delay = 0 }, signal) => {
  const { line, reverse } = findWire(from, to);
  const token = wb.token({ label, tone: reply ?? reverse ? "reply" : "request" });
  signal.addEventListener("abort", () => token.remove(), { once: true });

  await wait(delay, signal);
  if (!signal.aborted) await wb.travel(token, line.path, { reverse, signal });
};

let running = null;

wb.onFrame((frame) => {
  running?.abort();
  running = new AbortController();
  light();
  for (const step of movesOf(frame)) move(step, running.signal);
});
